import{_ as r,o as t,c as p,a2 as s}from"./chunks/framework.B2QVIpOM.js";const u=JSON.parse('{"title":"港大同学会书院 · 2020-21年度 · 中一 · 面试","description":"","frontmatter":{"schema":"exam-report-v3","generated_from":"assets/exam-feedback","school_slug":"school-28724523","school_zh":"港大同学会书院","school_en":"—","grade":"s1","year":"2020-21","year_label":"2020-21年度","type":"interview","title":"港大同学会书院 · 2020-21年度 · 中一 · 面试","anonymous":true,"source_ids":["C1821-HKUGAC-2021-FINAL","C1821-HKUGAC-2021-FIRST"],"rounds":["r2","r1"]},"headers":[],"relativePath":"reports/school-28724523/s1/2020-21-interview.md","filePath":"reports/school-28724523/s1/2020-21-interview.md"}'),e={name:"reports/school-28724523/s1/2020-21-interview.md"};function n(a,o,g,c,l,i){return t(),p("div",null,[...o[0]||(o[0]=[s('<h1 id="港大同学会书院-·-2020-21年度-·-中一-·-面试" tabindex="-1">港大同学会书院 · 2020-21年度 · 中一 · 面试 <a class="header-anchor" href="#港大同学会书院-·-2020-21年度-·-中一-·-面试" aria-label="Permalink to &quot;港大同学会书院 · 2020-21年度 · 中一 · 面试&quot;">​</a></h1><p><a href="/hk-exam-web/schools/school-28724523">← 返回港大同学会书院资料库</a></p><blockquote><p>以下内容根据考试及面试资料整理，已作匿名化与书面化处理，非逐字实录。具体安排请以当次考试通知为准。</p></blockquote><h2 id="record-c1821-hkugac-2021-final" tabindex="-1">资料来源：【其它机构】升中面试经验汇总_18-21.pdf <a class="header-anchor" href="#record-c1821-hkugac-2021-final" aria-label="Permalink to &quot;资料来源：【其它机构】升中面试经验汇总_18-21.pdf {#record-c1821-hkugac-2021-final}&quot;">​</a></h2><p><strong>资料类型：</strong> 不同学生的历史面试反馈汇编</p><p><strong>入学途径：</strong> 中一入学</p><p><strong>课程分支：</strong> 课程分支未注明</p><h3 id="第二轮-·-原文明示" tabindex="-1">第二轮 · 原文明示 <a class="header-anchor" href="#第二轮-·-原文明示" aria-label="Permalink to &quot;第二轮 · 原文明示&quot;">​</a></h3><blockquote><p><strong>考核安排：</strong></p><p><strong>准备任务后深入会面</strong></p><p>最后阶段包含小组／准备任务，再与老师或校长交流。不同考生遇到不同主题，以下按任务版本并列。</p></blockquote><blockquote><p><strong>小组任务：</strong> 中文、英语</p><p><strong>全球暖化与物资选择</strong></p><p>一组3名学生、一位老师，使用不同颜色纸张分配两段英文文章的阅读；将白纸对折两次形成四格并在右下写中英文名。设定为全球暖化后人们需要搬迁，按要求写画物品，从5件中选择不带哪件并用中文说明原因，再用英语写朋友的3个特质。考生记得物资包括罐头、电筒和绳索，其余未完整记下。</p><p><strong>疫情超级英雄</strong></p><p>另一组先用英语谈疫情中想做什么工作，再设计超级英雄：左上写中英文名，左下用中文写能力，右上写英雄名字，右下用英文写能力或特色。</p><p><strong>手机改造与发明家</strong></p><p>5名学生通过Zoom轮流朗读手机主题英文文章，每人约2至3次；创意改造手机为其他物品并介绍用途，用中文写发明家的特质。此组折纸后在右上写姓名。</p><p><strong>动物自我画像</strong></p><p>画最能形容自己的动物，在旁分别写3个中文和3个英文形容词。</p></blockquote><blockquote><p><strong>学生面谈：</strong> 英语及中文</p><p><strong>学习、职责与兴趣追问</strong></p><p>问为何选长笛、为何最喜欢数学、担任风纪遇过什么挫折、哪科较难及怎样记住难学内容。另问为何选乒乓球或游泳、从运动中学到什么、自己的优势与不足、最难忘旅行和地点及原因。</p><p><strong>申请资料与择校</strong></p><p>先展示刚才的任务纸并说明做了什么；按申请表追问为何形容学生像困在笼中、为何学西班牙语及是否想出国。另问如何认识港同、是否听过简介会、还报了哪些直资或传统名校、是否已有录取，以及路程远会否不便。</p></blockquote><blockquote><p><strong>家长面谈：</strong> 语言未注明</p><p><strong>会前问卷与停课学习</strong></p><p>会前问卷了解停课期间原小学如何安排、家长怎样支持、哪些学习表现满意或需改善，以及教育期望和未来升学计划。会面时可能沿回答追问，如孩子下午如何度过。</p><p><strong>教育心得与学校适配</strong></p><p>为什么选港同、挑选直资学校的准则、为何认为孩子适合、第一印象及是否参加简介会，分享教养心得并讨论想增加哪种活动。也有请孩子分别说一件感谢父母的事情，最后回应家庭预先提出的升中准备问题。</p></blockquote><h2 id="record-c1821-hkugac-2021-first" tabindex="-1">资料来源：【其它机构】升中面试经验汇总_18-21.pdf <a class="header-anchor" href="#record-c1821-hkugac-2021-first" aria-label="Permalink to &quot;资料来源：【其它机构】升中面试经验汇总_18-21.pdf {#record-c1821-hkugac-2021-first}&quot;">​</a></h2><p><strong>资料类型：</strong> 不同学生的历史面试反馈汇编</p><p><strong>入学途径：</strong> 中一入学</p><p><strong>课程分支：</strong> 课程分支未注明</p><h3 id="第一轮-·-原文明示" tabindex="-1">第一轮 · 原文明示 <a class="header-anchor" href="#第一轮-·-原文明示" aria-label="Permalink to &quot;第一轮 · 原文明示&quot;">​</a></h3><blockquote><p><strong>考核安排：</strong></p><p><strong>分房网上面试</strong></p><p>一组约10分钟，英语和中文各约5分钟，按不同链接进入面试房，中文房需输入考生编号。部分题目准备1分钟或1分15秒；告别派对题准备1分钟、讲述2分钟。</p></blockquote><blockquote><p><strong>语文：</strong> 普通话、粤语</p><p><strong>指定词语创作与解释</strong></p><p>普通话讲故事的词组包括：雕刻、晶莹剔透、刮目相看、感恩；醒来、美轮美奂、轻松、不堪一击；风风火火、难过、调虎离山、聊天；抛高、如火如荼、珠光宝气、惊讶。最后一组有人限时1.5分钟，其余故事的限时不完全相同。</p><p><strong>词义与创作追问</strong></p><p>粤语说明故事灵感和选材原因，用“刮目相看”造句，解释“调虎离山”，再举另一个带“虎”的成语并解释；给出“难过”或“美轮美奂”的近义表达，讲见过什么美轮美奂的事物。也会问社会是否需要感恩及原因。</p><p><strong>寓言与诗歌</strong></p><p>阅读“下金蛋的鹅”并谈寓意和感受，举出其他寓言及道理；一组明确要求不要选“小红帽”和“丑小鸭”。另有两篇山主题诗，及《友情伞》，问主要描写什么、除了雨伞还可用什么比喻友情。</p><p><strong>新闻观点</strong></p><p>口罩诈骗新闻：普通话谈感受，粤语说预防受骗的方法。另有一则青少年沉迷游戏、成绩下降后轻生的新闻，分别用普通话和粤语谈看法及是否认同其处理方式。</p></blockquote><blockquote><p><strong>英语：</strong> 英语</p><p><strong>学校制度与学习选择</strong></p><p>学校引入麦当劳作食堂是否合适，快餐有什么便利、不赞成时建议卖什么？英语授课学校是否应要求除小息外全日用英语沟通？功课应否让学生自行选择，若没有这些功课能否取得好成绩？中学生是否应该学乐器，学习者是否更有优势，并结合自己经历比较。</p><p><strong>为同学策划与提供帮助</strong></p><p>为即将离校、随和、勤奋、有艺术创意且喜欢Netflix、宠物、涂鸦及咖啡店的同学设计欢送活动、游戏或礼物；另问如何帮助新转校生，或怎样建议一名数学成绩差、担心父母生气的同学。</p><p><strong>烹饪、考察与经历</strong></p><p>烹饪课有什么益处、如何建立关系、喜欢什么食物、会做什么菜、烹饪时需要做什么？说服认为长洲考察无益的同学参加。分享最难忘的晚餐或旅行经历，以及疫情不能旅行是否难过。</p></blockquote>',20)])])}const d=r(e,[["render",n]]);export{u as __pageData,d as default};
